def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # Maps key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove the key if it exists (to re-insert it at the end)
            if key in cache:
                del cache[key]

            # If cache is at capacity and key is new, evict LRU
            if len(cache) >= capacity:
                cache.popitem(last=False)

            # Insert the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache:
                value, write_time = cache[key]
                # Check if expired
                if t >= write_time + ttl:
                    # Expired, treat as absent
                    results.append(-1)
                else:
                    # Not expired, return value and mark as most recently used
                    results.append(value)
                    # Move to end (most recently used)
                    del cache[key]
                    cache[key] = (value, write_time)
            else:
                results.append(-1)

    return results

